const emails = $input.all().map(i => {
  const j = i.json;
  const from = (j.from && j.from.text) || j.From || j.from || '';
  return {
    from: String(from).slice(0, 80),
    subject: j.subject || j.Subject || '',
    body: String(j.text || j.snippet || '').replace(/\s+/g, ' ').slice(0, 400)
  };
});
return [{ json: { emails, count: emails.length } }];

const raw = String($input.first().json.text || $input.first().json.output || '');
let d;
try {
  const s = raw.indexOf('{'); const e = raw.lastIndexOf('}');
  d = JSON.parse(raw.slice(s, e + 1).replace(/,\s*([\]}])/g, '$1'));
} catch (e) {
  return [{ json: { message: 'Digest parse failed: ' + e.message + '\n\n' + raw.slice(-400) } }];
}

const label = $('Window').first().json.label;
const esc = function (s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const b = function (s) { return '<b>' + esc(s) + '</b>'; };
const num = function (v) { return Number(String(v).replace(/[^0-9.]/g, '')) || 0; };
const inr = function (n) { return 'INR ' + n.toLocaleString('en-IN', { maximumFractionDigits: 2 }); };
const cap = function (s) { return s ? s.charAt(0).toUpperCase() + s.slice(1) : ''; };
const prIcon = { High: '🔴', Medium: '🟡', Low: '🟢' };

const tx = d.transactions || [];
let debit = 0, credit = 0;
tx.forEach(function (t) { if (t.type === 'credit') credit += num(t.amount); else debit += num(t.amount); });
const txIcon = function (t) { return t.type === 'credit' ? '🟢' : (num(t.amount) >= 1000 ? '🔴' : '🟠'); };

let msg = '📬 ' + b('Inbox digest · ' + label) + '\n';

if (tx.length) {
  msg += '\n💳 ' + b('TRANSACTIONS (' + tx.length + ')') + '\n';
  msg += '📉 Debited: ' + b(inr(debit)) + '\n📈 Credited: ' + b(inr(credit)) + '\n\n';
  tx.sort(function (a, c) { return num(c.amount) - num(a.amount); }).forEach(function (t) {
    msg += txIcon(t) + ' ' + (t.type === 'credit' ? 'Received ' : 'Spent ') + inr(num(t.amount)) +
      ' · ' + b(t.merchant) + ' (' + esc(cap(t.category)) + ')\n   ' + esc(t.summary) + '\n';
  });
}

const jobs = d.jobs || [];
if (jobs.length) {
  msg += '\n💼 ' + b('JOBS & INTERVIEWS (' + jobs.length + ')') + '\n';
  jobs.forEach(function (j) {
    msg += (prIcon[j.priority] || '⚪') + ' ' + b(j.company) + ' · ' + esc(j.role) + '\n   ' + esc(j.summary) +
      (j.action ? '\n   ➜ ' + esc(j.action) : '') + '\n';
  });
}

const li = d.linkedin || [];
if (li.length) {
  msg += '\n🔗 ' + b('LINKEDIN ALERTS (' + li.length + ')') + '\n';
  li.forEach(function (l) {
    const comps = (l.companies || []).filter(Boolean).map(b).join(', ');
    const roles = (l.roles || []).filter(Boolean).map(esc).join(', ');
    if (!comps && !roles) return;
    msg += '• ' + (roles || 'Roles') + '\n   Companies: ' + (comps || 'not listed') + '\n';
  });
}

const who = function (i) { return b(i.from) + (i.via ? ' via ' + esc(i.via) : ''); };
const imp = d.important || [];
if (imp.length) {
  msg += '\n⚠️ ' + b('IMPORTANT (' + imp.length + ')') + '\n';
  imp.forEach(function (i) { msg += '🔴 ' + who(i) + ' · ' + esc(i.subject) + '\n   ' + esc(i.summary) + '\n'; });
}

const oth = d.other || [];
if (oth.length) {
  msg += '\n📌 ' + b('OTHER (' + oth.length + ')') + '\n';
  oth.forEach(function (o) { msg += '• ' + who(o) + ': ' + esc(o.summary) + '\n'; });
}

if (!tx.length && !jobs.length && !li.length && !imp.length && !oth.length) msg += '\nNothing important in this window.';
return [{ json: { message: msg.slice(0, 4000) } }];

const now = $now;
const h = now.hour;
let end, start, label;
if (h < 9) {
  end = now.set({ hour: 6, minute: 0, second: 0, millisecond: 0 });
  start = end.minus({ hours: 12 }); label = 'Morning (6 PM – 6 AM)';
} else if (h < 15) {
  end = now.set({ hour: 12, minute: 0, second: 0, millisecond: 0 });
  start = end.minus({ hours: 6 }); label = 'Midday (6 AM – 12 PM)';
} else {
  end = now.set({ hour: 18, minute: 0, second: 0, millisecond: 0 });
  start = end.minus({ hours: 6 }); label = 'Evening (12 PM – 6 PM)';
}
return [{ json: {
  label: label,
  afterEpoch: Math.floor(start.toSeconds()),
  beforeEpoch: Math.floor(end.toSeconds())
} }];
